cd /workspace && python3 submission/scheduler.py < examples/stream.json > /tmp/out.json; python3 - << 'EOF'
import json
a=json.load(open('/tmp/out.json'))
b=json.load(open('/workspace/examples/stream.expected.json'))
import sys
def diff(x,y,path=''):
    if type(x)!=type(y):
        print(path, 'type', repr(x)[:80], repr(y)[:80]); return
    if isinstance(x,dict):
        for k in set(x)|set(y):
            if k not in x: print(path+'/'+k,'missing in got', repr(y[k])[:80])
            elif k not in y: print(path+'/'+k,'extra in got', repr(x[k])[:80])
            else: diff(x[k],y[k],path+'/'+k)
    elif isinstance(x,list):
        if len(x)!=len(y): print(path,'len',len(x),len(y))
        for i in range(min(len(x),len(y))): diff(x[i],y[i],path+'[%d]'%i)
    else:
        if x!=y: print(path,'val',repr(x)[:80],repr(y)[:80])
diff(a,b)
EOF
